%[text] # `ShowTaylor` calculates and displays Taylor polynomial approximations
%[text] The arguments are:
%[text] -  `fh`, a function handle identifying the function to be approximated
%[text] -  `deg`, the order, or vector of orders, of the Taylor polynomial(s) to be used
%[text] -  `bds`, a length two vector of doubles identifying the domain to use for plotting the results
%[text] -  `x0` is a double identifying the center, `x=x0`, of the Taylor polynomial approximation \
%[text] `ShowTaylor` creates and displays a plot of the original function and its approximates of order `deg`. If `deg` is a vector, then each approximation is displayed for 0.2 seconds to animate the series. This is intended to be used to watch approximations improving with increasing order, but it is not limited to that. 
%[text] ## Example
%[text] `ShowTaylor(@cos,[3,7,15],[-2*pi 2*pi],0)` graphs the function $y=\\cos(x)${"altText":"y = cos(x)"} over the domain $x \\in \[-2\\pi,2\\pi\]${"altText":"x in \[-2pi, 2pi\]"}. Then it computes the Taylor polynomials of degree three, seven, and fifteen, and produces three plots:
%[text]{"align":"center"} ![A graph of y=cos(x) overlayed by a graph of the third-order Taylor polynomial y\_3 which overlaps well in \[-0.5,0.5\] and follows the trend for \[-1.5,1.5\].](text:image:5bfa)![A plot of y=cos(x) overlayed with the 7th order Taylor polynomial y\_7 which agrees well on \[-2,2\] and follows the trend on \[-3,3\].](text:image:2838)![A plot of y=cos(x) overlayed with the 15th order Taylor polynomial y\_{15} which agrees well on \[-5.8,5.8\] and follows the trend in the region shown.](text:image:6f29)
function ShowTaylor(fh,deg,bds,x0)
arguments
    fh function_handle
    deg (1,:) {mustBePositive,mustBeFinite,mustBeInteger}
    bds (1,2) {mustBeNumeric}
    x0 (1,1) {mustBeNumeric,mustBeFinite}
end
if length(deg) > 1
    for k = 1:length(deg)
        CalcTaylor(fh,deg(k),bds,x0)
        pause(0.2)
    end
else
    CalcTaylor(fh,deg,bds,x0)
end

end

%%
function CalcTaylor(fh,deg,bds,x0)
% CalcTaylor computes and plots a Taylor polynomial approximation
%   fh is a function handle
%   deg is the degree of the Taylor polynomial
%   bds are the x limits of the range to be plotted
%   x0 is the center value for the approximation, x=x0
syms x
T = taylor(fh(x),x,x0,"Order",deg);
xVals = linspace(bds(1),bds(2),100);
fVals = fh(xVals);
plot(xVals,fVals);
hold on
TVals = double(subs(T,x,xVals));
plot(xVals,TVals);
hold off
title("A Taylor approximation of degree " + deg)
subtitle("Centered around $x =$" + x0,"Interpreter","latex")
xlabel("$x$","Interpreter","latex")
ylabel("$f(x)$","Interpreter","latex")
scale = (max(fVals)-min(fVals))*0.1;
ylim([min(fVals)-scale max(fVals)+scale])
xlim(bds)
legend(["Original" "Taylor Approximation"],"Location","southwest")
end



